Now I have all the context needed. Here's how to build your MCP server:

---

### **Program.cs** — stdio transport with DI

```csharp
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

var builder = Host.CreateApplicationBuilder(args);

// CRITICAL: log to stderr only — stdout is the JSON-RPC transport
builder.Logging.AddConsole(options =>
    options.LogToStandardErrorThreshold = LogLevel.Trace);

builder.Services.AddHttpClient();  // registers IHttpClientFactory + HttpClient

builder.Services.AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();

await builder.Build().RunAsync();
```

### **ApiTools.cs** — tool class wrapping a REST API

```csharp
using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    [McpServerTool, Description("Get a user by their ID from the REST API.")]
    public async Task<string> GetUser(
        [Description("The numeric user ID")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching user {UserId}", userId);
        return await httpClient.GetStringAsync(
            $"https://jsonplaceholder.typicode.com/users/{userId}",
            cancellationToken);
    }

    [McpServerTool, Description("List all posts, optionally filtered by user ID.")]
    public async Task<string> ListPosts(
        [Description("Filter posts by this user ID (optional)")] int? userId = null,
        CancellationToken cancellationToken = default)
    {
        var url = "https://jsonplaceholder.typicode.com/posts";
        if (userId.HasValue)
            url += $"?userId={userId.Value}";

        var json = await httpClient.GetStringAsync(url, cancellationToken);
        var posts = JsonSerializer.Deserialize<JsonElement>(json);
        return JsonSerializer.Serialize(posts, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerTool(ReadOnly = true), Description("Search posts by title keyword.")]
    public async Task<string> SearchPosts(
        [Description("Keyword to search for in post titles")] string keyword,
        CancellationToken cancellationToken = default)
    {
        var json = await httpClient.GetStringAsync(
            "https://jsonplaceholder.typicode.com/posts", cancellationToken);
        var posts = JsonSerializer.Deserialize<JsonElement>(json);

        var matches = posts.EnumerateArray()
            .Where(p => p.GetProperty("title").GetString()!
                .Contains(keyword, StringComparison.OrdinalIgnoreCase))
            .Select(p => p.ToString());

        return $"[{string.Join(",", matches)}]";
    }
}
```

---

### How DI works for MCP tools

The SDK has two injection styles:

| Style | How it works |
|-------|-------------|
| **Constructor injection** (non-static class) | DI services go in the constructor — like `ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)` above. The class is instantiated per-call. |
| **Method parameter injection** (static class) | DI services appear as method params alongside tool params. The SDK resolves them automatically. |

**Key rule:** The SDK distinguishes tool parameters from injected services by type. These types are **auto-injected and hidden from the LLM schema**:
- `CancellationToken`
- `HttpClient`, `ILogger<T>`, or any DI-registered service
- `IMcpServer`, `IProgress<ProgressNotificationValue>`

Only parameters with `[Description]` are exposed to the LLM.

### Scaffold & run

```bash
dotnet new mcpserver -n MyApiServer
# Replace the generated files with the code above
cd MyApiServer
dotnet build && dotnet run
```

The server will start and listen for JSON-RPC messages on stdin. Connect it from VS Code, GitHub Copilot, or test with `MCP Inspector` (see `mcp-csharp-debug` skill).
